import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String userInput = scanner.nextLine();
        List<Character> charsList = new ArrayList<>();
        boolean foundAtSymbol = true;

        for (int idx = 0; idx < userInput.length(); idx++) {
            char c = userInput.charAt(idx);
            if (idx >= 2 && idx < userInput.length() && userInput.substring(idx - 2, idx + 1).equals("dot") && idx != userInput.length() - 1 && idx != 2) {
                // Remove last two characters
                if (charsList.size() >= 2) {
                    charsList.remove(charsList.size() - 1);
                    charsList.remove(charsList.size() - 1);
                }
                // Append '.'
                charsList.add('.');
            } else if (idx >= 1 && idx < userInput.length() && userInput.substring(idx - 1, idx + 1).equals("at") && foundAtSymbol && idx != 1 && idx != userInput.length() - 1) {
                // Remove last character
                if (!charsList.isEmpty()) {
                    charsList.remove(charsList.size() - 1);
                }
                // Append '@'
                charsList.add('@');
                foundAtSymbol = false;
            } else {
                charsList.add(c);
            }
        }

        StringBuilder resultStr = new StringBuilder();
        for (char ch : charsList) {
            resultStr.append(ch);
        }
        System.out.println(resultStr.toString());
        scanner.close();
    }
}
